insert into public.stage_playbook (sort, stage, period, supabase, you, lessons) values
  (1, 'Pre-launch', 'Supabase: Dec 2019 to May 2020', 'Interviewed developers, picked VC-backed startups as the ideal customer, then built. Changed the tagline the day before the Hacker News post that put them on the map.', 'Interview 20 developers before writing code. Write your ideal-customer sentence and name 20 teams. Run the tagline test and the stopwatch on the incumbent.', '11, 1, 2, 3'),
  (2, 'Launch to first traction', 'Supabase: May 2020 to 2021', 'Top of Hacker News, YC S20, $6M seed, first Launch Week. The CEO posted many of the big stories himself.', 'One big launch moment built around the borrowed category. Post in public as the founder every week. Teach the standard. Start a launch cadence and measure signups, not stars.', '12, 2, 4, 5, 6'),
  (3, 'Early revenue', 'Supabase: 2021 to 2023', 'Free until production, usage-triggered outreach, launch weeks at peak lift.', 'Find your production signal and charge from it. Run founder-led triggered outreach with a control group. Check what your next investors expect to see in revenue.', '7, 8'),
  (4, 'Scale', 'Supabase: 2023 onward', 'pgvector, AI app builders, coding agents. Launch weeks turn into retention.', 'Measure your AI visibility, build for agents, check which rituals still acquire users.', '5, 9'),
  (5, 'Always', 'Every stage', 'Raised over $1B and still runs remote, frugal and written down.', 'Retention before acquisition. Founder hours on user calls, however much you raise.', '10')
on conflict (sort) do update set stage = excluded.stage, period = excluded.period, supabase = excluded.supabase, you = excluded.you, lessons = excluded.lessons;

insert into public.dont_copy (n, title, body) values
  (1, 'The luck', 'Copplestone assumes agents will settle on about three defaults per category, and says getting picked takes a lot of luck: "I don''t like betting on luck." Do the fundamentals, and don''t build a plan that needs lightning to strike.'),
  (2, 'The insecure defaults', 'A 2025 scan of 1,645 apps built with Lovable found 170 (10.3%) exposing data through missing or misconfigured Row Level Security (CVE-2025-48757, which Lovable disputes). Fast setup without safe defaults becomes someone else''s breach and your headline. Make the safe path the fast path.'),
  (3, 'Concentration risk', 'If one partner sends most of your users, your growth depends on their roadmap. Supabase turned that risk into a product: Lovable Cloud and Bolt Cloud both run on Supabase.'),
  (4, 'Free usage as revenue', '4 million new databases a month is a vanity number until a slice of them pays.'),
  (5, 'Launch weeks forever', 'Measure the lift in signups, not stars, and change the format when it stops working. Supabase''s star lift fell every year we measured.'),
  (6, 'Free until real, in 2026 money', 'Supabase earned nothing for about 18 months on 2020 and 2021 money. Before you copy that, check what your next investors expect to see in revenue, and charge from your production signal early.')
on conflict (n) do update set title = excluded.title, body = excluded.body;

update public.faq set a = 'Three compounding moves. A new tagline, "the open source Firebase alternative", went live the day before an early user''s Hacker News post reached the top, and hosted databases went from 8 to 800 in three days. Relentless shipping, packaged as Launch Weeks, which Copplestone saw give "20% bumps each time" (their effect on GitHub stars faded every year). Then AI app builders and coding agents adopted Supabase as their default backend; by October 2026, 70% of new databases were created by agents or AI tools.' where n = 1;
update public.faq set a = 'The product did the marketing. Copplestone timed AWS (about 8.5 minutes from a new database to a first row) and got Supabase to about 5 seconds. The team polled developers on Hacker News, Reddit and Twitter, and turned releases into Launch Weeks. In his words: "if I could give a free database, I''d rather give that to developers than spending on marketing."' where n = 3;
update public.faq set a = 'Not for Supabase. Everything it builds is open source except the platform and billing code, the part it takes to host millions of databases. Customers pay for hosting, scale and not being on call. By Copplestone''s rough recollection, revenue took about 18 months to start, reached roughly $1M ARR by the end of the first year of charging, then about $7.5M the year after.' where n = 4;
update public.faq set a = 'One setup step gives a full Postgres database with auth, APIs and storage, and years of open source code, Reddit threads and GitHub discussions meant models already knew it well. Supabase then built for that traffic: Supabase for Platforms for app builders, and a CLI and MCP server for agents. By October 2026, Supabase said 70% of new databases were created by agents or AI tools.' where n = 5;
update public.faq set a = 'There''s no trick, and Supabase''s CEO says part of it is luck: if agents settle on about three defaults per category, most tools won''t be one. What you control: get developers to a result fast with as little input as possible, make the product fully operable from a CLI and MCP, publish clean docs, and answer questions in public where models can learn from them.' where n = 6;
update public.faq set a = 'Supabase''s CEO puts it bluntly: "we should not exist if AWS are so good. They''ve got way more cash than us." Cash wasn''t the deciding factor. Developer experience, open source trust and community were. When Copplestone timed it at the start, AWS took about 8.5 minutes from a new database to a first row; Supabase now takes about 5 seconds.' where n = 7;

delete from public.sources where n > 23;
