update public.diagnostic_questions set question = 'Can a developer get value in under 10 minutes without talking to you?' where n = 2;
update public.start_here set why = 'Half a day, one of the cheapest growth levers you have, and the result tells you what to fix first.' where n = 1;
update public.start_here set why = 'Day zero never stops mattering: Supabase went from an early target of under a minute to about 5 seconds.' where n = 12;
update public.templates set body_md = replace(body_md, 'Supabase''s benchmark: 8.5 minutes on AWS RDS, 5 seconds on Supabase.', 'Copplestone''s numbers: about 8.5 minutes on AWS RDS when he timed it at the start, about 5 seconds on Supabase today.') where id = 'stopwatch_audit';
update public.templates set body_md = replace(body_md, '- [ ] llms.txt at your docs root', '- [ ] llms.txt (a proposed standard) at your docs root') where id = 'ai_legibility';

update public.origins set event = 'Copplestone pitches the idea to Ant Wilson (they met through Entrepreneur First, per Contrary Research)' where at = '2019-12-01';
update public.origins set event = 'Founded; January spent interviewing developers' where at = '2020-01-01';
update public.origins set event = 'An early user''s Hacker News post reaches the top: 1,120 points, 366 comments. 522 new GitHub stars that day, still the repo''s biggest day in our data' where at = '2020-05-27';
update public.origins set event = 'YC S20; fully remote from the start' where at = '2020-07-01';
update public.origins set event = '$6M seed led by Coatue' where at = '2020-12-15';

update public.taglines set note = 'Sold as an add-on to "your existing PostgreSQL database". 8 hosted databases' where captured = '2020-05-25 09:07:56+00';
update public.taglines set note = 'Captured an hour after an early user''s Hacker News post went up. Typo and all. 800 hosted databases within 3 days' where captured = '2020-05-27 07:15:40+00';

