update public.revenue set period = 'First ~18 months', source = 'Paul Copplestone, YC Startup School (rough recollection)' where sort = 1;
update public.revenue set period = 'End of first year of charging', source = 'Paul Copplestone, YC Startup School (rough recollection)' where sort = 2;
update public.revenue set source = 'Paul Copplestone, YC Startup School (rough recollection)' where sort = 3;

update public.ai_waves set driver = 'Bolt.new and Lovable made Supabase their default backend. By late December 2024, Supabase said it was getting DDoSed by the databases they created.' where id = 2;
update public.ai_waves set driver = 'Claude Code, Codex and others create databases straight from the CLI and MCP. Claude Code has been the largest contributor since the start of 2026 (Series F announcement).' where id = 3;
update public.developer_experience set primary_interface = 'CLI and MCP, heading toward declarative schemas in Git and branchable environments' where id = 3;

update public.rounds set closed = '2024-09-25', closed_label = 'Sep 2024', note = null where closed = '2024-09-01';
update public.rounds set round = 'Growth round + Turso deal', note = 'Not a named series; no valuation disclosed; Turso terms undisclosed' where closed = '2026-10-02';
update public.rounds set note = 'Led by Coatue with Y Combinator, Mozilla and angels (TechCrunch)' where closed = '2020-12-15';

update public.known_issues set detail = 'A 2025 scan of 1,645 apps built with Lovable found 170 (10.3%) exposing data through missing or misconfigured Row Level Security (CVE-2025-48757, which Lovable disputes). On Hacker News, "Supabase MCP can leak your entire SQL database" (July 2025) drew 848 points and 470 comments.' where id = 1;

update public.case_queries set columns = '[{"name": "captured_label", "type": "text", "format": "mono"}, {"name": "copy", "type": "text"}, {"name": "note", "type": "text"}]'::jsonb where id = 'taglines_history';
update public.case_queries set columns = '[{"name": "closed_label", "type": "text", "format": "mono"}, {"name": "round", "type": "text"}, {"name": "amount_usd", "type": "numeric", "format": "usd_compact"}, {"name": "valuation_usd", "type": "numeric", "format": "usd_compact", "null": "n/d"}, {"name": "lead", "type": "text"}]'::jsonb where id = 'rounds';

update public.case_queries set footer_right = 'n/d = not disclosed. Series E and F valuations are post-money' where id = 'rounds';
update public.case_queries set footer_right = 'lift = stars/day in the week ÷ stars/day in the 4 weeks before it, skipping the week just before. Source: OSS Insight (GH Archive)' where id = 'launch_week_lift';
